<script setup lang="ts">
import {computed,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {agentWorkData} from '@/pinia/agentWork';import ConfigEditor from './ConfigEditor.vue';import ProjectCreate from '@/views/AgentWork/views/projectCreate.view.vue';import {phaseSkills} from './catalog';import type {P1SkillId} from '@/views/AgentWork/interface';
const route=useRoute();const router=useRouter();const work=agentWorkData();const id=computed(()=>String(route.query.projectId||work.currentProjectId));const project=computed(()=>work.projects.find(p=>p.id===id.value));const tab=computed(()=>String(route.query.tab||'overview'));
watch(id,value=>{const p=work.projects.find(p=>p.id===value);if(p&&(work.currentProjectId!==value||work.workspaceMode!=='project'))work.switchProject(p);},{immediate:true});
function saved(ids:P1SkillId[]){if(project.value)project.value.skillIds=[...(project.value.skillIds||[]).filter(x=>!phaseSkills.some(s=>s.id===x)),...ids];}
function switchTab(value:string){router.replace({path:'/index/projects/detail',query:{projectId:id.value,tab:value}});}
</script>
<template><div class="p1-desk"><header><h1>编辑项目 · {{project?.name||'项目不存在'}}</h1><button @click="router.push('/index/projects')">返回项目管理</button></header><nav class="p1-tabs" aria-label="项目详情标签页"><button v-for="item in [{id:'overview',name:'项目概览'},{id:'skills',name:'技能'},{id:'config',name:'项目配置'}]" :key="item.id" :class="{active:tab===item.id}" @click="switchTab(item.id)">{{item.name}}</button></nav><template v-if="project"><section v-if="tab==='overview'"><h2>项目基本信息</h2><p>项目名称：{{project.name}}</p><p>项目编号：{{project.id}}</p><p>状态：{{project.status}}</p><p>本期范围：一装一卸；创建后监听四类基础事件及晚发晚到。</p><button @click="switchTab('skills')">编辑项目名称与技能</button></section><div v-if="tab==='skills'" style="height:calc(100% - 110px);min-height:620px"><ProjectCreate :key="id" embedded/></div><ConfigEditor v-if="tab==='config'" :key="id" :project-id="id" @saved="saved"/></template><p v-else>请返回项目管理选择项目。</p></div></template>
<style src="./phase.css"></style>
